def dms(value: float) -> str:
    total = round((value % 30) * 3600)
    d, rem = divmod(total, 3600)
    m, s = divmod(rem, 60)
    return f"{d:02d}d {m:02d}m {s:02d}s"


def classify(sidereal: float) -> dict:
    span = 360.0 / 27.0
    nak = int(sidereal / span)
    pada = int((sidereal % span) / (span / 4)) + 1
    return {
        "sign_index": int(sidereal // 30) % 12,
        "sign": RASHI[int(sidereal // 30) % 12],
        "degree_in_sign": sidereal % 30,
        "nakshatra_index": nak,
        "nakshatra": NAKSHATRA[nak],
        "pada": pada,
    }


def build_case(label: str, when: tuple, lat: float, lon: float, why: str) -> dict:
    y, mo, d, h, mi = when
    jd_ut = swe.julday(y, mo, d, h + mi / 60.0)

    ayan = {}
    for name, mode in AYANAMSHAS.items():
        swe.set_sid_mode(mode)
        ayan[name] = swe.get_ayanamsa_ut(jd_ut)

    swe.set_sid_mode(swe.SIDM_LAHIRI)
    lahiri = ayan["lahiri"]

    bodies = {}
    for name, planet in BODIES:
        values, _ = swe.calc_ut(jd_ut, planet, FLAGS)
        tropical, speed = values[0], values[3]
        sidereal = (tropical - lahiri) % 360.0
        entry = {"tropical": tropical, "sidereal": sidereal, "speed": speed,
                 "retrograde": speed < 0, "dms": dms(sidereal)}
        entry.update(classify(sidereal))
        bodies[name] = entry

    for name, planet in (("Rahu", swe.TRUE_NODE), ("Rahu_mean", swe.MEAN_NODE)):
        values, _ = swe.calc_ut(jd_ut, planet, FLAGS)
        tropical, speed = values[0], values[3]
        sidereal = (tropical - lahiri) % 360.0
        entry = {"tropical": tropical, "sidereal": sidereal, "speed": speed,
                 "retrograde": speed < 0, "dms": dms(sidereal)}
        entry.update(classify(sidereal))
        bodies[name] = entry

    ketu_trop = (bodies["Rahu"]["tropical"] + 180.0) % 360.0
    ketu = {"tropical": ketu_trop,
            "sidereal": (ketu_trop - lahiri) % 360.0,
            "speed": bodies["Rahu"]["speed"],
            "retrograde": bodies["Rahu"]["retrograde"],
            "dms": dms((ketu_trop - lahiri) % 360.0)}
    ketu.update(classify(ketu["sidereal"]))
    bodies["Ketu"] = ketu

    cusps, ascmc = swe.houses_ex(jd_ut, lat, lon, b"W")
    asc_trop, mc_trop = ascmc[0], ascmc[1]
    lagna = {"tropical": asc_trop, "sidereal": (asc_trop - lahiri) % 360.0}
    lagna.update(classify(lagna["sidereal"]))
    mc = {"tropical": mc_trop, "sidereal": (mc_trop - lahiri) % 360.0}
    mc.update(classify(mc["sidereal"]))

    return {
        "label": label,
        "why": why,
        "utc": datetime.datetime(y, mo, d, h, mi).isoformat(),
        "jd_ut": jd_ut,
        "delta_t_seconds": swe.deltat(jd_ut) * 86400.0,
        "latitude": lat,
        "longitude": lon,
        "ayanamsha": ayan,
        "bodies": bodies,
        "lagna": lagna,
        "midheaven": mc,
    }


def find_boundary_crossings() -> list[dict]:
    """
    Locate moments where a body sits just outside a sign, nakshatra or pada
    boundary, at an angular offset large enough that the application's measured
    accuracy for that body cannot change the classification. These cases test
    that the whole pipeline — longitude, ayanamsha, sign, nakshatra, pada —
    lands on the correct side of a boundary.
    """
    swe.set_sid_mode(swe.SIDM_LAHIRI)
    span = 360.0 / 27.0

    # Offset from the boundary, in degrees: three times the measured worst-case
    # error of the application for that body, floored at 0.01°.
    offsets = {
        "Chandra": 0.012, "Surya": 0.016, "Budha": 0.023, "Shukra": 0.035,
        "Mangal": 0.084, "Guru": 0.33, "Shani": 0.49,
    }

    targets = [
        ("sign", 30.0, swe.MOON, "Chandra", 2451545.0),
        ("nakshatra", span, swe.MOON, "Chandra", 2447404.0),
        ("pada", span / 4, swe.MOON, "Chandra", 2440000.0),
        ("sign", 30.0, swe.SUN, "Surya", 2451545.0),
        ("nakshatra", span, swe.SUN, "Surya", 2447404.0),
        ("pada", span / 4, swe.SUN, "Surya", 2455000.0),
        ("sign", 30.0, swe.MERCURY, "Budha", 2451545.0),
        ("nakshatra", span, swe.MERCURY, "Budha", 2448000.0),
        ("sign", 30.0, swe.JUPITER, "Guru", 2447404.0),
        ("pada", span / 4, swe.VENUS, "Shukra", 2455000.0),
        ("nakshatra", span, swe.MARS, "Mangal", 2453000.0),
        ("sign", 30.0, swe.SATURN, "Shani", 2450000.0),
        ("sign", 30.0, swe.VENUS, "Shukra", 2452000.0),
        ("nakshatra", span, swe.SATURN, "Shani", 2445000.0),
    ]

    def sidereal_at(jd: float, planet: int) -> float:
        values, _ = swe.calc_ut(jd, planet, FLAGS)
        return (values[0] - swe.get_ayanamsa_ut(jd)) % 360.0

    results = []
    for kind, width, planet, name, start_jd in targets:
        step = 0.02 if planet == swe.MOON else 0.5
        offset = offsets[name]

        # Walk forward to a boundary crossing, then bisect onto each side of it
        # at the required angular offset.
        previous = sidereal_at(start_jd, planet)
        jd = start_jd
        boundary_value = None
        low = high = None
        for _ in range(40000):
            jd += step
            current = sidereal_at(jd, planet)
            if abs(current - previous) > 180:
                previous = current
                continue
            if int(previous / width) != int(current / width):
                boundary_value = int(max(previous, current) / width) * width
                low, high = jd - step, jd
                break
            previous = current
        if boundary_value is None:
            continue
        forward = sidereal_at(high, planet) > sidereal_at(low, planet)

        for side, target in (("before", boundary_value - offset),
                             ("after", boundary_value + offset)):
            lo, hi = low - 6 * step, high + 6 * step
            for _ in range(90):
                mid = (lo + hi) / 2
                value = sidereal_at(mid, planet)
                ahead = value > target if forward else value < target
                if ahead:
                    hi = mid
                else:
                    lo = mid
            jd_case = (lo + hi) / 2
            values, _ = swe.calc_ut(jd_case, planet, FLAGS)
            ayan = swe.get_ayanamsa_ut(jd_case)
            sidereal = (values[0] - ayan) % 360.0
            if abs((sidereal - target + 180) % 360 - 180) > 1e-4:
                continue                     # bisection did not converge; skip
            entry = {
                "label": f"{name}_{kind}_{side}",
                "body": name,
                "kind": kind,
                "jd_ut": jd_case,
                "offset_from_boundary_deg": offset if side == "after" else -offset,
                "ayanamsha_lahiri": ayan,
                "tropical": values[0],
                "sidereal": sidereal,
                "speed": values[3],
            }
            entry.update(classify(sidereal))
            results.append(entry)
    return results


def main():
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    data = {
        "generator": {
            "tool": "tools/generate_reference.py",
            "source": "Swiss Ephemeris (pyswisseph) with SEFLG_MOSEPH",
            "swisseph_version": swe.version,
            "generated": datetime.datetime.now().isoformat(timespec="seconds"),
            "note": ("Independent of the application's own theory. "
                     "The application never imports swisseph."),
        },
        "cases": [build_case(*case) for case in CASES],
        "boundaries": find_boundary_crossings(),
    }
    with open(OUT, "w", encoding="utf-8") as fh:
        json.dump(data, fh, indent=1, sort_keys=True)
    print(f"wrote {OUT}")
    print(f"  cases: {len(data['cases'])}   boundary cases: {len(data['boundaries'])}")


if __name__ == "__main__":
    sys.exit(main())
